            text_sha256: string;
            /** Format: date-time */
            effective_from: string;
            purpose: components["schemas"]["ConsentPurpose"];
            /** @description Nội dung điều khoản; server kiểm SHA-256 khớp text_sha256 trước khi trả */
            text_vi: string;
